import { Component, computed, input } from '@angular/core';
import type { EChartsOption } from 'echarts';
import { HrmChart } from './hrm-chart';

/** 1 tiêu chí năng lực + mức tối đa của thang. */
export interface HrmCompetency {
  name: string;
  max?: number;
}

/** hrm-competency-radar — biểu đồ mạng nhện so sánh năng lực HIỆN TẠI vs YÊU CẦU vị trí,
 *  làm bật GAP (khoảng chênh) đa tiêu chí. Vùng tô giúp thấy ngay tiêu chí nào còn thiếu.
 *  Domain HRM: đánh giá năng lực, lộ trình phát triển, khung năng lực vị trí. */
@Component({
  selector: 'hrm-competency-radar',
  imports: [HrmChart],
  template: `<hrm-chart [option]="option()" [height]="height()" />`,
  host: { class: 'hrm-competency-radar' },
})
export class HrmCompetencyRadar {
  /** Danh sách tiêu chí năng lực (trục của mạng nhện). */
  readonly competencies = input<HrmCompetency[]>([]);
  /** Điểm hiện tại theo từng tiêu chí (cùng thứ tự competencies). */
  readonly current = input<number[]>([]);
  /** Điểm yêu cầu của vị trí (cùng thứ tự). Bỏ trống = chỉ hiện hiện tại. */
  readonly required = input<number[]>([]);
  /** Nhãn 2 chuỗi — bên gọi cấp (i18n). */
  readonly currentLabel = input('Hiện tại');
  readonly requiredLabel = input('Yêu cầu');
  /** Thang tối đa mặc định nếu competency không đặt max. */
  readonly maxScale = input(5);
  readonly height = input(320);
  /** Ghi đè palette (2 màu: hiện tại · yêu cầu). Bỏ trống = palette theme (--data-*). */
  readonly color = input<string[] | null>(null);

  protected readonly option = computed<EChartsOption>(() => {
    const comps = this.competencies();
    const req = this.required();
    const hasReq = req.length > 0;
    const series = [{ value: this.current(), name: this.currentLabel(), areaStyle: { opacity: 0.18 } }];
    if (hasReq) series.push({ value: req, name: this.requiredLabel(), areaStyle: { opacity: 0.08 } });
    const c = this.color();
    return {
      ...(c && c.length ? { color: c } : {}),
      tooltip: {},
      legend: { bottom: 0 },
      radar: {
        indicator: comps.map((c) => ({ name: c.name, max: c.max ?? this.maxScale() })),
        radius: '66%',
        splitNumber: this.maxScale(),
      },
      series: [{ type: 'radar', symbolSize: 5, lineStyle: { width: 2 }, data: series }],
    };
  });
}
